using System.Text.Json;

namespace PeerSync.TestFixtures;

// These are public synthetic secrets. Independently generated by Python/OpenSSL,
// not by the production HKDF/Base32/CRC/Ed25519 implementations under test.
internal static class FolderKeyVectors
{
    public static IEnumerable<JsonElement> All()
    {
        using var document = JsonDocument.Parse(File.ReadAllText(
            Path.Combine(AppContext.BaseDirectory, "Fixtures", "folder-key-vectors.json")));
        return document.RootElement.GetProperty("vectors").EnumerateArray().Select(v => v.Clone()).ToArray();
    }

    public static byte[] Bytes(this JsonElement vector, string property) =>
        Convert.FromHexString(vector.GetProperty(property).GetString()!);

    public static string Text(this JsonElement vector, string property) =>
        vector.GetProperty(property).GetString()!;
}
